        symbols_count: 0,
        entry: StepIdx::ZERO,
        resource_contract: ResourceContract::DEFAULT,
        step_names: Box::from([]),
        input_slots,
    };
    CompiledWorkflow::try_from_parts(parts).map_err(|error| error.to_string().into())
}

